=Sei un consulente esperto di concorsi pubblici e selezioni di lavoro in Italia.
Valuta quanto ciascuno dei bandi seguenti è adatto al candidato.

=== PROFILO CANDIDATO ===
Sintesi: {{ $json.sintesi }}
Livello di istruzione: {{ $json.livelloIstruzione }}
Competenze tecniche: {{ $json.competenze }}
Ruoli adatti: {{ $json.profiliAdatti }}
Patenti: {{ $json.patenti || 'non indicate' }}
Regione: {{ $json.regione }}
Disponibilità: {{ $json.disponibilita }}

=== BANDI DA VALUTARE ({{ $json.numeroBandi }}) ===
{{ $json.testoBandi }}

=== CRITERI DI PUNTEGGIO (0-100) ===
- 0-29: incompatibile (manca un requisito obbligatorio, es. laurea, abilitazione o patente specifica).
- 30-59: possibile ma poco coerente con il profilo.
- 60-79: buona corrispondenza.
- 80-100: ottima corrispondenza con competenze e ruoli adatti.
- Se la sede è nella regione del candidato e la sua disponibilità non è "Ovunque in Italia", aggiungi fino a 10 punti.
- Se un requisito non è indicato nel bando, NON inventarlo: segnalalo come "da verificare nel bando".
Scrivi motivazione e requisiti in italiano, in modo breve e concreto.

Valuta OGNI bando dell'elenco, nessuno escluso, e riporta per ciascuno esattamente il suo id.
Rispondi esclusivamente con un oggetto JSON valido, senza testo prima o dopo e senza blocchi di codice. Il campo "punteggio" deve essere un numero intero, "consigliato" deve essere true o false.

parameters.jsonSchemaExample:
{
  "valutazioni": [
    {
      "id": "bb46987d62ae4f67b3e4262e1e5ffcb2",
      "punteggio": 75,
      "motivazione": "Spiegazione breve del perché il bando è adatto o no",
      "requisitiDaVerificare": "Eventuali requisiti mancanti o da controllare",
      "consigliato": true
    }
  ]
}

parameters.jsCode:
// Punteggio minimo per ricevere la notifica (deve essere uguale a "Prepara righe inviati")
const SOGLIA = 60;

// Protegge i caratteri speciali per l'HTML di Telegram
const escape = (testo) => String(testo ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Etichetta in cima al messaggio, in base alla fonte
const ETICHETTE_FONTE = {
  'InPA': '🏛 BANDO PUBBLICO · InPA',
  'LinkedIn': '💼 ANNUNCIO · LinkedIn',
};

const messaggi = [];
const risposte = $input.all(); // un elemento per utente

for (let i = 0; i < risposte.length; i++) {
  // L'utente che ha generato questa risposta (con i suoi bandi candidati)
  const utente = $('Abbina bandi e utenti').itemMatching(i).json;
  const valutazioni = risposte[i].json.output?.valutazioni ?? [];

  // Indice dei bandi candidati di QUESTO utente, per trovarli tramite id
  const bandiPerId = {};
  for (const b of utente.candidati) bandiPerId[b.id] = b;

  const scelti = valutazioni
    .filter(v => bandiPerId[v.id] && v.punteggio >= SOGLIA) // id valido e punteggio sufficiente
    .map(v => ({ ...bandiPerId[v.id], ...v }))               // unisce bando + valutazione
    .sort((a, b) => b.punteggio - a.punteggio);              // dal migliore

  for (const b of scelti) {
    const icona = b.punteggio >= 80 ? '🟢' : '🟡';
    const etichetta = ETICHETTE_FONTE[b.fonte] ?? `📌 ${escape(b.fonte)}`; // fonti future: mostra il nome
    const testoLink = b.fonte === 'InPA' ? 'Apri il bando' : "Apri l'annuncio";

    const righe = [
      `<i>${etichetta}</i>`,
      `${icona} <b>${b.punteggio}/100 — ${escape(b.figura || b.titolo)}</b>`,
      `🏢 ${escape(b.ente)}`,
      `📍 ${escape(b.sede)}${b.inRegione ? ' ⭐' : ''}`,
      `⏳ Scadenza: ${escape(b.scadenza)}`,
      '',
      `💬 ${escape(b.motivazione)}`,
    ];
    if (b.requisitiDaVerificare) righe.push(`⚠️ Da verificare: ${escape(b.requisitiDaVerificare)}`);
    righe.push('', `🔗 <a href="${b.link}">${testoLink}</a>`);

    // Ogni messaggio porta con sé il chat Telegram del SUO utente
    messaggi.push({ json: { chatId: utente.telegramChatId, testo: righe.join('\n') } });
  }
}

return messaggi;

