// === CONFIGURAZIONE ===
const MAX_BANDI_PER_UTENTE = 15; // protegge il limite giornaliero di Gemini
const RICHIEDONO_LAUREA = ['funzionari', 'elevata qualificazione', 'dirigent'];

// I bandi normalizzati: sono gli stessi per tutti gli utenti.
// Gli avvisi di mobilità li escludiamo per tutti (riservati a chi è già dipendente pubblico).
const bandi = $('Merge').all()
  .map(item => item.json)
  .filter(b => !(b.categoria || '').toLowerCase().includes('mobilit'));

// === LE TRE REGOLE ===

// Regola 1: titolo di studio (già pronta, usala come esempio)
// Chi ha la laurea vede tutto; chi non ce l'ha non vede i profili che la richiedono.
function passaIstruzione(bando, utente) {
  const haLaurea = (utente.livelloIstruzione || '').startsWith('laurea');
  if (haLaurea) return true;
  const testo = `${bando.titolo} ${bando.figura}`.toLowerCase();
  return !RICHIEDONO_LAUREA.some(parola => testo.includes(parola));
}

// Regola 2: parole chiave  
// utente.paroleChiave è un TESTO, es. "informatic, sviluppat, web".
// Deve restituire true se ALMENO UNA parola compare nel titolo o nella figura del bando.

function passaParoleChiave(bando, utente) {
  // "informatic, sviluppat, web" → ["informatic", "sviluppat", "web"]
  const parole = (utente.paroleChiave || '')
    .split(',')                         // spezza il testo a ogni virgola
    .map(p => p.trim().toLowerCase())   // toglie gli spazi e mette in minuscolo
    .filter(p => p.length > 0);         // scarta eventuali pezzi vuoti (es. virgola finale)

  // Il testo del bando in cui cercare: solo titolo e figura (non la descrizione)
  const testo = `${bando.titolo} ${bando.figura}`.toLowerCase();

  // true se ALMENO UNA parola dell'utente compare nel testo del bando
  return parole.some(parola => testo.includes(parola));
}

// Regola 3
// Se la disponibilità dell'utente contiene la parola "solo"
//   → il bando passa solo se la sua sede contiene la regione dell'utente.
// In tutti gli altri casi → il bando passa sempre.
// Attenzione al minuscolo su tutti e tre i testi (disponibilità, sede, regione).
function passaZona(bando, utente) {
  const disponibilita = (utente.disponibilita || '').toLowerCase();

  // "Preferibilmente..." e "Ovunque..." → nessun vincolo geografico
  if (!disponibilita.includes('solo')) return true;

  // "Solo nella mia regione" → la sede del bando deve contenere la regione dell'utente
  const regione = (utente.regione || '').toLowerCase();
  const sede = (bando.sede || '').toLowerCase();
  return regione.length > 0 && sede.includes(regione);
}

// Memoria: le coppie "utente|bando" già valutate in passato.
// Un Set è una lista che permette di controllare MOLTO velocemente se un valore c'è.
const giaInviati = new Set(
  $('Leggi inviati').all()
    .map(item => item.json)
    .filter(r => r.email && r.idBando) // ignora l'elemento vuoto se la tabella è vuota
    .map(r => `${r.email.toLowerCase()}|${r.idBando}`)
);

// === ABBINAMENTO (già pronto) ===
const risultati = [];

for (const item of $('Leggi utenti').all()) {
  const utente = item.json;

  // Senza chat Telegram non possiamo avvisarlo: lo saltiamo
  if (!utente.telegramChatId) continue;

  const regione = (utente.regione || '').toLowerCase();

  const candidati = bandi
        .filter(b => !giaInviati.has(`${(utente.email || '').toLowerCase()}|${b.id}`))
        .filter(b => !b.soloPer || b.soloPer === (utente.email || '').toLowerCase())
    .filter(b => passaIstruzione(b, utente) && passaZona(b, utente) && passaParoleChiave(b, utente))
    .map(b => ({ ...b, inRegione: (b.sede || '').toLowerCase().includes(regione) }))
    .sort((a, b) => b.inRegione - a.inRegione) // prima quelli nella regione dell'utente
    .slice(0, MAX_BANDI_PER_UTENTE);

  // Nessun bando adatto oggi: niente chiamata AI, niente messaggio
  if (candidati.length === 0) continue;

  // Il profilo nel database è testo: lo ritrasformiamo in oggetto
  const profilo = JSON.parse(utente.profilo || '{}');

  // Il testo dei bandi per il prompt (un blocco per bando, con l'id ben visibile)
  const testoBandi = candidati.map(b => [
    `--- BANDO id=${b.id} ---`,
    `Titolo: ${b.titolo}`,
    `Figura: ${b.figura}`,
    `Ente: ${b.ente}`,
    `Sede: ${b.sede}`,
    `Scadenza: ${b.scadenza}`,
    `Descrizione: ${(b.descrizione || '').slice(0, 600)}`
  ].join('\n')).join('\n\n');

  risultati.push({
    json: {
      email: utente.email,
      nome: utente.nome,
      telegramChatId: utente.telegramChatId,
      regione: utente.regione,
      disponibilita: utente.disponibilita,
      livelloIstruzione: utente.livelloIstruzione,
      patenti: utente.patenti,
      sintesi: profilo.sintesi,
      competenze: (profilo.competenzeTecniche || []).join(', '),
      profiliAdatti: (profilo.profiliAdatti || []).join(', '),
      numeroBandi: candidati.length,
      candidati,
      testoBandi
    }
  });
}

return risultati;

// La tua email: deve essere IDENTICA a quella della tabella utenti (in minuscolo).
// ⚠️ Prima di caricare il workflow su GitHub, sostituiscila con un segnaposto.
//const PROPRIETARIO = 'LA_TUA_EMAIL@gmail.com';
const PROPRIETARIO = 'vincenzo.calvaruso17@gmail.com';
// Righe da ignorare quando cerchiamo titolo/azienda/luogo
const RUMORE = [
  /^il tuo avviso/i,   // intestazione dell'email
  /^-{3,}$/,           // eventuali righe separatrici "-----"
];

// Map = "dizionario" id → offerta: se la stessa offerta compare in due avvisi, la teniamo una volta sola
const offerte = new Map();

for (const item of $input.all()) {
  const testo = item.json.text || '';

  // Nome dell'avviso (es. “Sviluppatore Web” (Italia)): lo passiamo all'AI come contesto
  const avviso = (testo.match(/avviso di offerte di lavoro per (.+)/i) || [])[1] || '';

  // Ogni offerta termina con questa riga. Le parentesi "catturano" il link e l'id numerico.
  // Accettiamo anche "View job:" nel caso di avvisi in inglese.
  const regexLink = /(?:Visualizza offerta di lavoro|View job):\s*(https:\/\/www\.linkedin\.com\/comm\/jobs\/view\/(\d+)\S*)/gi;

  let inizioBlocco = 0;
  for (const match of testo.matchAll(regexLink)) {
    const idOfferta = match[2];

    // Il testo tra il link precedente e questo = i dati di questa offerta
    const blocco = testo.slice(inizioBlocco, match.index);
    inizioBlocco = match.index + match[0].length;

    const righe = blocco.split('\n')
      .map(r => r.trim())
      .filter(r => r.length > 0 && !RUMORE.some(re => re.test(r)));

    const [titolo, azienda, luogo] = righe; // le prime tre righe utili
    if (!titolo || offerte.has(idOfferta)) continue;

    // Stesso formato di "Normalizza bandi", così il resto del motore non cambia
    offerte.set(idOfferta, {
      id: `linkedin-${idOfferta}`,
      fonte: 'LinkedIn',
      titolo,
      figura: titolo,
      ente: azienda || 'Non indicata',
      sede: luogo || 'Non indicata',
      categoria: 'Offerta di lavoro privata',
      posti: null,
      scadenza: 'Non indicata',
      descrizione: avviso ? `Trovata dall'avviso LinkedIn: ${avviso}` : '',
      link: `https://www.linkedin.com/jobs/view/${idOfferta}/`,
      linkEsterno: null,
      soloPer: PROPRIETARIO.toLowerCase(), // questa offerta è SOLO per te
    });
  }
}

return [...offerte.values()].map(o => ({ json: o }));

// Deve essere uguale alla SOGLIA di "Prepara messaggi"
const SOGLIA = 60;

const righe = [];
const risposte = $input.all(); // un elemento per utente

for (let i = 0; i < risposte.length; i++) {
  const utente = $('Abbina bandi e utenti').itemMatching(i).json;
  const valutazioni = risposte[i].json.output?.valutazioni ?? [];

  // I bandi candidati di questo utente, per ritrovarli tramite id
  const bandiPerId = {};
  for (const b of utente.candidati) bandiPerId[b.id] = b;

  for (const v of valutazioni) {
    const b = bandiPerId[v.id];
    if (!b) continue; // id sconosciuto (l'AI ha sbagliato): non salviamo niente

    righe.push({
      json: {
        email: (utente.email || '').toLowerCase(),
        idBando: b.id,
        fonte: b.fonte,
        titolo: b.figura || b.titolo,
        link: b.link,
        punteggio: Number(v.punteggio) || 0,
        notificato: v.punteggio >= SOGLIA, // true = è stato mandato su Telegram
      }
    });
  }
}

return righe;
